OLD = ("Old Replicon case study (replicon.com/case-study/, archived 2023 via Wayback; site now redirects to Deltek). Content mostly 2010-2019 — "
       "stale, current use NOT confirmed. Brief record, not enriched beyond a site scan. ")
def old(slug, name, ind, country, status="POSSIBLE", reason="Stale (pre-2020) vendor story; current use unknown", conf=25, **k):
    d = dict(company_name=name, industry=ind, hq_country=country, vendor=V, evidence_type=CS,
             evidence_summary="Archived Replicon case study about %s (%s)." % (name, ind),
             source_url=RB + slug + "/", second_source_url="https://web.archive.org/web/2023/https://www.replicon.com/case-study/%s/" % slug,
             source_publication_date="", status=status, status_reason=reason, confidence_score=conf,
             pitch_angle="Long-time Replicon (now Deltek) user — Deltek pricing/forced migration angle; verify current tool first")
    d.update(k)
    d["notes"] = OLD + k.get("notes", "")
    return d
